package com.example.minicommerce.payment.infrastructure;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;@Repository public class PaymentWebhookRepository{private final JdbcTemplate jdbc;public PaymentWebhookRepository(JdbcTemplate j){jdbc=j;}public boolean claim(String eventId,String payload){return jdbc.update("insert into payment_webhook_events(provider_event_id,payload,received_at) values (?,?,now()) on conflict do nothing",eventId,payload)==1;}}
